// WP-2.1 GPU clustered lighting: see include/fuse/renderer/lighting/gpu/clustered_lighting.hpp.
#include <fuse/renderer/lighting/gpu/clustered_lighting.hpp>

#include <fuse/renderer/deferred/gbuffer.hpp>
#include <fuse/renderer/lighting/clustered_kernel.hpp>
#include <fuse/renderer/lighting/ltc/ltc_lut.hpp>
#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <algorithm>
#include <cstring>
#include <initializer_list>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by cmake/rp_wp21.cmake from shaders/lighting/*: kLc<Kernel><Slang|Glsl>Spv and
// FUSE_LIGHTING_GPU_{SLANG,GLSL} when every kernel of a language exists.
#include "lighting_gpu_spv.h"
#endif

namespace fuse::renderer::lighting_gpu {

namespace {
constexpr u32 kPushBytes = sizeof(LightingPush);
constexpr u32 kFrameStride = 1024u; ///< ring slot size (>= sizeof(LightingFrameConstants), 256-aligned)
static_assert(sizeof(LightingFrameConstants) <= kFrameStride, "frame ring slot");
constexpr u32 kOutputFormat = static_cast<u32>(GpuFormat::R16G16B16A16Sfloat);
/// G-buffer attachments the shade reads (GBufferAttachment order): RT0, RT1, RT2, RT4, RT5.
constexpr u32 kGBufferAttachments[5] = {0u, 1u, 2u, 4u, 5u};

BufferUsage bufferUsage(std::initializer_list<BufferUsage> bits) {
    u32 u = 0;
    for (const BufferUsage b : bits) {
        u |= static_cast<u32>(b);
    }
    return static_cast<BufferUsage>(u);
}

ImageUsage imageUsage(std::initializer_list<ImageUsage> bits) {
    u32 u = 0;
    for (const ImageUsage b : bits) {
        u |= static_cast<u32>(b);
    }
    return static_cast<ImageUsage>(u);
}

u64 align256(u64 v) { return (v + 255u) & ~u64{255u}; }

u32 groups(u32 items, u32 size) { return items == 0u ? 1u : (items + size - 1u) / size; }

#if defined(FUSE_VULKAN_BACKEND)
struct Code {
    const u32* words = nullptr;
    usize bytes = 0;
};
template <usize N>
Code code(const u32 (&spv)[N]) {
    return Code{spv, sizeof(spv)};
}
#endif
} // namespace

LightingBufferLayout LightingBufferLayout::compute(u32 clusterCount, u32 slicesZ, u32 capacity, u32 lightCapacity) {
    LightingBufferLayout l{};
    u64 cursor = 0;
    auto take = [&](u64 bytes) {
        const u64 at = cursor;
        cursor = align256(cursor + std::max<u64>(bytes, 4u));
        return at;
    };
    l.aabbs = take(static_cast<u64>(clusterCount) * sizeof(GpuClusterAabb));
    l.bounds = take(static_cast<u64>(lightCapacity) * sizeof(GpuLightBounds));
    l.sliceCounts = take(static_cast<u64>(kMaxSlicesZ) * 4u);
    l.sliceLights = take(static_cast<u64>(slicesZ) * lightCapacity * 4u);
    l.clusterCounts = take(static_cast<u64>(clusterCount) * 4u);
    l.clusterDropped = take(static_cast<u64>(clusterCount) * 4u);
    l.clusterSlots = take(static_cast<u64>(clusterCount) * capacity * 4u);
    l.workBytes = cursor;
    cursor = 0;
    l.header = take(sizeof(LightListHeader));
    l.grid = take(static_cast<u64>(clusterCount) * 8u);
    l.directional = take(static_cast<u64>(lightCapacity) * 4u);
    l.lightList = take(static_cast<u64>(clusterCount) * capacity * 4u);
    l.listsBytes = cursor;
    return l;
}

LightingCapabilities queryLightingCapabilities(const VulkanDevice* device) {
    LightingCapabilities c{};
#if defined(FUSE_VULKAN_BACKEND)
    if (device == nullptr || !device->isValid()) {
        return c;
    }
    const RendererCaps& caps = device->info().caps;
    if (!caps.bufferDeviceAddress || !caps.shaderInt64) {
        c.reason = "bufferDeviceAddress / shaderInt64 missing";
        return c;
    }
    VkFormatProperties props{};
    vkGetPhysicalDeviceFormatProperties(static_cast<VkPhysicalDevice>(device->nativePhysicalDevice()),
                                        static_cast<VkFormat>(kOutputFormat), &props);
    if ((props.optimalTilingFeatures & VK_FORMAT_FEATURE_STORAGE_IMAGE_BIT) == 0u) {
        c.reason = "RGBA16F storage images unsupported";
        return c;
    }
    c.lighting = true;
    c.reason = "ok";
#else
    (void)device;
    c.reason = "stub backend";
#endif
    return c;
}

ClusteredLighting::~ClusteredLighting() { destroy(); }

bool ClusteredLighting::init(const ClusteredLightingDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.allocator == nullptr || desc.bindless == nullptr || desc.framesInFlight == 0u) {
        return false;
    }
    if (!queryLightingCapabilities(desc.device).lighting) {
        return false;
    }
    m_clusters = ClusterDesc::clampCounts(desc.clusters);
    if (m_clusters.clusterCount() == 0u) {
        return false;
    }
    m_capacity = m_clusters.maxLightsPerCluster == 0u ? kMaxLightsPerCluster : m_clusters.maxLightsPerCluster;
    m_clusters.maxLightsPerCluster = m_capacity;
    m_retired.reserve(8);
    m_initialized = true; // destroy() releases partial state from here on
    BufferDesc ring{};
    ring.size = static_cast<usize>(desc.framesInFlight) * kFrameStride;
    ring.usage = bufferUsage({BufferUsage::Storage, BufferUsage::ShaderDeviceAddress});
    ring.memoryUsage = MemoryUsage::CpuToGpu;
    ring.name = "clustered_lighting.frame";
    const u32 lightCapacity = std::max(desc.lightCapacity, 1u);
    if (!m_desc.allocator->createBuffer(ring, m_frameRing) || m_frameRing.mapped == nullptr ||
        m_frameRing.deviceAddress == 0u || !createPipelines() || !createBuffers(m_buffers, lightCapacity, m_layout) ||
        (desc.width > 0u && desc.height > 0u && !createOutput(m_output, desc.width, desc.height))) {
        destroy();
        return false;
    }
    if (desc.energyCompensation) {
        // WP-2.2: the BRDF / LTC LUT, baked once per process, uploaded once (read-only afterwards).
        const ltc::BrdfLut& lut = ltc::sharedBrdfLut();
        BufferDesc lutDesc{};
        lutDesc.size = static_cast<usize>(lut.bytes());
        lutDesc.usage = bufferUsage({BufferUsage::Storage, BufferUsage::ShaderDeviceAddress});
        lutDesc.memoryUsage = MemoryUsage::CpuToGpu;
        lutDesc.name = "clustered_lighting.brdf_lut";
        if (!lut.valid() || !m_desc.allocator->createBuffer(lutDesc, m_lutBuffer) || m_lutBuffer.mapped == nullptr ||
            m_lutBuffer.deviceAddress == 0u) {
            destroy();
            return false;
        }
        std::memcpy(m_lutBuffer.mapped, lut.data(), static_cast<usize>(lut.bytes()));
        m_brdfLut = lut.data();
    }
    m_lightCapacity = lightCapacity;
    if (desc.width > 0u && desc.height > 0u) {
        m_width = desc.width;
        m_height = desc.height;
        m_stats.outputRebuilds = 1u;
    }
    m_stats.bufferRebuilds = 1u;
    return true;
#else
    return false;
#endif
}

void ClusteredLighting::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    collectRetired(~0ull);
    Retired current{};
    current.buffers[0] = m_buffers.work;
    current.buffers[1] = m_buffers.lists;
    current.image = m_output.image;
    current.slots[0] = m_output.slot;
    for (u32 i = 0; i < kGBufferInputs; ++i) {
        current.slots[1u + i] = m_gbufferSlots[i];
    }
    destroyRetired(current);
    if (m_frameRing.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_frameRing);
    }
    if (m_lutBuffer.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_lutBuffer);
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    for (void*& pipeline : m_pipelines) {
        if (pipeline != nullptr) {
            vkDestroyPipeline(device, static_cast<VkPipeline>(pipeline), nullptr);
            pipeline = nullptr;
        }
    }
    if (m_layoutHandle != nullptr) {
        vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(m_layoutHandle), nullptr);
    }
#endif
    m_layoutHandle = nullptr;
    m_buffers = Buffers{};
    m_output = Output{};
    m_frameRing = Buffer{};
    m_frameAddress = 0;
    m_lutBuffer = Buffer{};
    m_brdfLut = nullptr;
    m_retired.clear();
    m_gbuffer = nullptr;
    for (u32 i = 0; i < kGBufferInputs; ++i) {
        m_gbufferImages[i] = nullptr;
        m_gbufferSlots[i] = BindlessSlotHandle{};
        m_gbufferHandles[i] = 0u;
    }
    m_width = m_height = 0;
    m_capacity = m_lightCapacity = m_lightCount = 0;
    m_recordCount = 0;
    m_language = "none";
    m_stats = LightingStats{};
    m_initialized = false;
}

bool ClusteredLighting::createPipelines() {
#if defined(FUSE_VULKAN_BACKEND)
    Code k[kKernelCount]{};
    bool found = false;
#if defined(FUSE_LIGHTING_GPU_SLANG)
    if (m_desc.language == LightingKernelLanguage::Auto || m_desc.language == LightingKernelLanguage::Slang) {
        k[kBounds] = code(kLcBoundsSlangSpv);
        k[kBin] = code(kLcBinSlangSpv);
        k[kCull] = code(kLcCullSlangSpv);
        k[kScan] = code(kLcScanSlangSpv);
        k[kCompact] = code(kLcCompactSlangSpv);
        k[kShade] = code(kLcShadeSlangSpv);
        m_language = "slang";
        found = true;
    }
#endif
#if defined(FUSE_LIGHTING_GPU_GLSL)
    if (!found && (m_desc.language == LightingKernelLanguage::Auto || m_desc.language == LightingKernelLanguage::Glsl)) {
        k[kBounds] = code(kLcBoundsGlslSpv);
        k[kBin] = code(kLcBinGlslSpv);
        k[kCull] = code(kLcCullGlslSpv);
        k[kScan] = code(kLcScanGlslSpv);
        k[kCompact] = code(kLcCompactGlslSpv);
        k[kShade] = code(kLcShadeGlslSpv);
        m_language = "glsl";
        found = true;
    }
#endif
    if (!found) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle());
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, kPushBytes};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.setLayoutCount = setLayout != VK_NULL_HANDLE ? 1u : 0u;
    layoutInfo.pSetLayouts = &setLayout;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    m_layoutHandle = layout;
    const VkPipelineCreateFlags createFlags = static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags());
    for (u32 i = 0; i < kKernelCount; ++i) {
        VkShaderModuleCreateInfo moduleInfo{};
        moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
        moduleInfo.codeSize = k[i].bytes;
        moduleInfo.pCode = k[i].words;
        VkShaderModule module = VK_NULL_HANDLE;
        if (vkCreateShaderModule(device, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
            return false;
        }
        VkComputePipelineCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
        info.flags = createFlags;
        info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        info.stage.module = module;
        info.stage.pName = "main";
        info.layout = layout;
        VkPipeline pipeline = VK_NULL_HANDLE;
        const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
        vkDestroyShaderModule(device, module, nullptr);
        m_pipelines[i] = pipeline;
        if (result != VK_SUCCESS) {
            return false;
        }
    }
    return true;
#else
    return false;
#endif
}

bool ClusteredLighting::createBuffers(Buffers& b, u32 lightCapacity, LightingBufferLayout& layout) {
    b = Buffers{};
    layout = LightingBufferLayout::compute(m_clusters.clusterCount(), m_clusters.slicesZ, m_capacity, lightCapacity);
    const BufferUsage usage = bufferUsage({BufferUsage::Storage, BufferUsage::ShaderDeviceAddress, BufferUsage::TransferSrc});
    BufferDesc work{};
    work.size = static_cast<usize>(layout.workBytes);
    work.usage = usage;
    work.memoryUsage = MemoryUsage::GpuOnly;
    work.name = "clustered_lighting.work";
    BufferDesc lists = work;
    lists.size = static_cast<usize>(layout.listsBytes);
    lists.name = "clustered_lighting.lists";
    const bool ok = m_desc.allocator->createBuffer(work, b.work) && b.work.deviceAddress != 0u &&
                    m_desc.allocator->createBuffer(lists, b.lists) && b.lists.deviceAddress != 0u;
    if (!ok) {
        if (b.work.handle != nullptr) {
            m_desc.allocator->destroyBuffer(b.work);
        }
        if (b.lists.handle != nullptr) {
            m_desc.allocator->destroyBuffer(b.lists);
        }
        b = Buffers{};
    }
    return ok;
}

bool ClusteredLighting::createOutput(Output& o, u32 width, u32 height) {
    o = Output{};
    TextureDesc d{};
    d.width = width;
    d.height = height;
    d.format = static_cast<GpuFormat>(kOutputFormat);
    d.usage = imageUsage({ImageUsage::Storage, ImageUsage::Sampled, ImageUsage::TransferSrc});
    d.name = "clustered_lighting.output";
    if (!m_desc.allocator->createImage(d, o.image)) {
        o = Output{};
        return false;
    }
    o.slot = m_desc.bindless->registerTextureSlot(o.image, true);
    if (!o.slot.isValid()) {
        m_desc.allocator->destroyImage(o.image);
        o = Output{};
        return false;
    }
    return true;
}

void ClusteredLighting::retire(Retired r) {
    r.serial = m_frameSerial;
    m_retired.push_back(r);
    ++m_stats.retired;
}

void ClusteredLighting::destroyRetired(Retired& r) {
    for (BindlessSlotHandle& slot : r.slots) {
        if (slot.isValid()) {
            m_desc.bindless->unregisterSlot(slot);
        }
    }
    for (Buffer& b : r.buffers) {
        if (b.handle != nullptr) {
            m_desc.allocator->destroyBuffer(b);
        }
    }
    if (r.image.image != nullptr) {
        m_desc.allocator->destroyImage(r.image);
    }
    r = Retired{};
}

u32 ClusteredLighting::collectRetired(u64 completedSerial) {
    u32 collected = 0;
    usize keep = 0;
    for (usize i = 0; i < m_retired.size(); ++i) {
        if (m_retired[i].serial > completedSerial) {
            m_retired[keep++] = m_retired[i];
            continue;
        }
        destroyRetired(m_retired[i]);
        ++collected;
    }
    m_retired.resize(keep);
    m_stats.retired = m_stats.retired >= collected ? m_stats.retired - collected : 0u;
    return collected;
}

bool ClusteredLighting::bindGBuffer(const material_resolve::MaterialResolve& gbuffer) {
    bool changed = m_gbuffer != &gbuffer;
    for (u32 i = 0; i < kGBufferInputs && !changed; ++i) {
        changed = gbuffer.gbufferImage(kGBufferAttachments[i]).image != m_gbufferImages[i];
    }
    if (!changed) {
        return true;
    }
    Retired old{};
    bool any = false;
    for (u32 i = 0; i < kGBufferInputs; ++i) {
        old.slots[1u + i] = m_gbufferSlots[i];
        any = any || m_gbufferSlots[i].isValid();
        m_gbufferSlots[i] = BindlessSlotHandle{};
        m_gbufferImages[i] = nullptr;
        m_gbufferHandles[i] = 0u;
    }
    if (any) {
        retire(old);
    }
    m_gbuffer = &gbuffer;
    for (u32 i = 0; i < kGBufferInputs; ++i) {
        const Texture& image = gbuffer.gbufferImage(kGBufferAttachments[i]);
        if (image.image == nullptr) {
            return false;
        }
        m_gbufferSlots[i] = m_desc.bindless->registerTextureSlot(image, false);
        if (!m_gbufferSlots[i].isValid()) {
            return false;
        }
        m_gbufferImages[i] = image.image;
        m_gbufferHandles[i] = m_desc.bindless->shaderHandle(m_gbufferSlots[i]);
    }
    ++m_stats.gbufferBinds;
    return true;
}

bool ClusteredLighting::beginFrame(u64 frameSerial, const LightingFrameDesc& frame) {
    if (!m_initialized || m_buffers.work.handle == nullptr) {
        return false;
    }
    m_frameSerial = frameSerial;
    m_recordCount = 0;
    m_stats.assignmentPasses = 0;
    m_stats.shadePasses = 0;
    m_lightCount = frame.lightCount;
    if (frame.lightCount > m_lightCapacity) {
        u32 grown = m_lightCapacity;
        while (grown < frame.lightCount) {
            grown = grown > 0x40000000u ? frame.lightCount : grown * 2u;
        }
        Buffers fresh{};
        LightingBufferLayout layout{};
        if (!createBuffers(fresh, grown, layout)) {
            return false;
        }
        Retired old{};
        old.buffers[0] = m_buffers.work;
        old.buffers[1] = m_buffers.lists;
        retire(old);
        m_buffers = fresh;
        m_layout = layout;
        m_lightCapacity = grown;
        ++m_stats.bufferRebuilds;
    }
    if (frame.gbuffer != nullptr) {
        const u32 w = frame.gbuffer->width();
        const u32 h = frame.gbuffer->height();
        if (w == 0u || h == 0u) {
            return false;
        }
        if (w != m_width || h != m_height || m_output.image.image == nullptr) {
            Output fresh{};
            if (!createOutput(fresh, w, h)) {
                return false;
            }
            if (m_output.image.image != nullptr) {
                Retired old{};
                old.image = m_output.image;
                old.slots[0] = m_output.slot;
                retire(old);
            }
            m_output = fresh;
            m_width = w;
            m_height = h;
            ++m_stats.outputRebuilds;
        }
        if (!bindGBuffer(*frame.gbuffer)) {
            return false;
        }
    }

    LightingFrameConstants c{};
    const u64 work = m_buffers.work.deviceAddress;
    const u64 lists = m_buffers.lists.deviceAddress;
    c.aabbs = work + m_layout.aabbs;
    c.bounds = work + m_layout.bounds;
    c.sliceCounts = work + m_layout.sliceCounts;
    c.sliceLights = work + m_layout.sliceLights;
    c.clusterCounts = work + m_layout.clusterCounts;
    c.clusterDropped = work + m_layout.clusterDropped;
    c.clusterSlots = work + m_layout.clusterSlots;
    c.listHeader = lists + m_layout.header;
    c.grid = lists + m_layout.grid;
    c.directional = lists + m_layout.directional;
    c.lightList = lists + m_layout.lightList;
    c.brdfLut = m_lutBuffer.deviceAddress;
    c.shadowsLo = static_cast<u32>(frame.shadows & 0xFFFFFFFFu); // WP-3.2 VsmShadowConstants (0 = unshadowed)
    c.shadowsHi = static_cast<u32>(frame.shadows >> 32u);
    // The oracle's camera resolution (clustered_kernel::make_camera): same basis, same tangents.
    const clustered_kernel::CameraView view = clustered_kernel::make_camera(frame.camera);
    const math::Vec3 vecs[4] = {view.position, view.right, view.up, view.back};
    f32* dst[4] = {c.cameraPosition, c.right, c.up, c.back};
    for (u32 i = 0; i < 4u; ++i) {
        dst[i][0] = vecs[i].x;
        dst[i][1] = vecs[i].y;
        dst[i][2] = vecs[i].z;
    }
    c.nearPlane = view.near_plane;
    c.farPlane = view.far_plane;
    c.tanX = view.tan_x;
    c.tanY = view.tan_y;
    std::memcpy(c.ambient, frame.ambient, sizeof(c.ambient));
    c.flags = view.reversed_z ? kFlagReversedZ : 0u;
    c.width = m_width;
    c.height = m_height;
    c.invWidth = m_width > 0u ? 1.f / static_cast<f32>(m_width) : 0.f;
    c.invHeight = m_height > 0u ? 1.f / static_cast<f32>(m_height) : 0.f;
    c.tilesX = m_clusters.tilesX;
    c.tilesY = m_clusters.tilesY;
    c.slicesZ = m_clusters.slicesZ;
    c.capacity = m_capacity;
    c.clusterCount = m_clusters.clusterCount();
    c.lightCount = frame.lightCount;
    c.lightCapacity = m_lightCapacity;
    c.scene = frame.scene;
    c.output = m_output.slot.isValid() ? m_desc.bindless->shaderHandle(m_output.slot) : 0u;
    c.gbufferNormalAo = m_gbufferHandles[0];
    c.gbufferAlbedo = m_gbufferHandles[1];
    c.gbufferRoughMetal = m_gbufferHandles[2];
    c.gbufferDepth = m_gbufferHandles[3];
    c.gbufferEmissive = m_gbufferHandles[4];
    // Edge tables with the oracle's expressions (clustered_kernel::build_cluster_aabb): slice depths
    // from slice_near_z / slice_far_z, tile edges (k / tiles) * 2 - 1 and 1 - (k / tiles) * 2.
    const u32 slices = m_clusters.slicesZ;
    for (u32 s = 0; s < slices; ++s) {
        c.sliceDepth[s] = clustered_kernel::slice_near_z(s, slices, view.near_plane, view.far_plane);
    }
    c.sliceDepth[slices] = clustered_kernel::slice_far_z(slices - 1u, slices, view.near_plane, view.far_plane);
    for (u32 x = 0; x <= m_clusters.tilesX; ++x) {
        c.ndcX[x] = (static_cast<f32>(x) / static_cast<f32>(m_clusters.tilesX)) * 2.f - 1.f;
    }
    for (u32 y = 0; y <= m_clusters.tilesY; ++y) {
        c.ndcY[y] = 1.f - (static_cast<f32>(y) / static_cast<f32>(m_clusters.tilesY)) * 2.f;
    }
    const u64 offset = (frameSerial % m_desc.framesInFlight) * kFrameStride;
    std::memcpy(static_cast<u8*>(m_frameRing.mapped) + offset, &c, sizeof(c));
    m_frameAddress = m_frameRing.deviceAddress + offset;
    return true;
}

LightingGraphRefs ClusteredLighting::importInto(rg::Graph& graph) {
    LightingGraphRefs refs{};
    if (!m_initialized || m_buffers.work.handle == nullptr) {
        return refs;
    }
    refs.work = graph.importBuffer(rg::ImportedBuffer{m_buffers.work.handle, m_buffers.work.desc.size, m_buffers.queues[0],
                                                      &m_buffers.queues[0], "clustered_lighting.work"});
    refs.lists = graph.importBuffer(rg::ImportedBuffer{m_buffers.lists.handle, m_buffers.lists.desc.size,
                                                       m_buffers.queues[1], &m_buffers.queues[1], "clustered_lighting.lists"});
    if (m_output.image.image != nullptr) {
        rg::ImportedImage i{};
        i.image = m_output.image.image;
        i.view = m_output.image.view;
        i.format = kOutputFormat;
        i.width = m_width;
        i.height = m_height;
        i.initialLayout = m_output.layout;
        i.initialQueue = m_output.queue;
        i.layoutTracker = &m_output.layout;
        i.queueTracker = &m_output.queue;
        i.name = "clustered_lighting.output";
        refs.output = graph.importImage(i);
    }
    return refs;
}

ClusteredLighting::PassRecord* ClusteredLighting::nextRecord() {
    if (m_recordCount >= kMaxPasses) {
        return nullptr;
    }
    PassRecord* r = &m_records[m_recordCount++];
    *r = PassRecord{};
    r->self = this;
    r->push.frame = m_frameAddress;
    return r;
}

void ClusteredLighting::addAssignment(rg::Graph& graph, const LightingGraphRefs& refs,
                                      const gpu_scene::GpuSceneGraphRefs& scene) {
    if (!m_initialized || !refs.work.valid() || !refs.lists.valid() || m_recordCount + 5u > kMaxPasses) {
        return;
    }
    const u32 clusters = m_clusters.clusterCount();
    auto record = [&](u32 kernel, u32 gx) {
        PassRecord* r = nextRecord();
        r->kernel = kernel;
        r->groups[0] = gx;
        return r;
    };
    {
        PassRecord* r = record(kBounds, groups(std::max(clusters, m_lightCount), kLinearGroup));
        rg::PassBuilder pass = graph.addPass("light.bounds", &ClusteredLighting::recordDispatch, r);
        gpu_scene::GpuScene::useAll(pass, scene, rg::Access::StorageRead, rg::kStageCompute);
        pass.use(refs.work, rg::Access::StorageReadWrite, {}, rg::kStageCompute);
    }
    {
        PassRecord* r = record(kBin, m_clusters.slicesZ + 1u);
        graph.addPass("light.bin", &ClusteredLighting::recordDispatch, r)
            .use(refs.work, rg::Access::StorageReadWrite, {}, rg::kStageCompute)
            .use(refs.lists, rg::Access::StorageReadWrite, {}, rg::kStageCompute);
    }
    {
        PassRecord* r = record(kCull, groups(clusters, kLinearGroup));
        graph.addPass("light.cull", &ClusteredLighting::recordDispatch, r)
            .use(refs.work, rg::Access::StorageReadWrite, {}, rg::kStageCompute);
    }
    {
        PassRecord* r = record(kScan, 1u);
        graph.addPass("light.scan", &ClusteredLighting::recordDispatch, r)
            .use(refs.work, rg::Access::StorageRead, {}, rg::kStageCompute)
            .use(refs.lists, rg::Access::StorageReadWrite, {}, rg::kStageCompute);
    }
    {
        PassRecord* r = record(kCompact, groups(clusters, kLinearGroup));
        graph.addPass("light.compact", &ClusteredLighting::recordDispatch, r)
            .use(refs.work, rg::Access::StorageRead, {}, rg::kStageCompute)
            .use(refs.lists, rg::Access::StorageReadWrite, {}, rg::kStageCompute);
    }
    ++m_stats.assignmentPasses;
}

void ClusteredLighting::addShade(rg::Graph& graph, const LightingGraphRefs& refs, const gpu_scene::GpuSceneGraphRefs& scene,
                                 const material_resolve::ResolveGraphRefs& gbufferRefs, rg::BufferRef dump,
                                 u64 dumpAddress) {
    if (!m_initialized || !refs.lists.valid() || !refs.output.valid() || m_gbuffer == nullptr) {
        return;
    }
    for (const u32 attachment : kGBufferAttachments) {
        if (!gbufferRefs.gbuffer[attachment].valid()) {
            return;
        }
    }
    PassRecord* r = nextRecord();
    if (r == nullptr) {
        return;
    }
    r->kernel = kShade;
    r->groups[0] = groups(m_width, kShadeTile);
    r->groups[1] = groups(m_height, kShadeTile);
    r->push.out = dump.valid() ? dumpAddress : 0u;
    rg::PassBuilder pass = graph.addPass("light.shade", &ClusteredLighting::recordDispatch, r);
    gpu_scene::GpuScene::useAll(pass, scene, rg::Access::StorageRead, rg::kStageCompute);
    pass.use(refs.lists, rg::Access::StorageRead, {}, rg::kStageCompute);
    for (const u32 attachment : kGBufferAttachments) {
        pass.use(gbufferRefs.gbuffer[attachment], rg::Access::SampledRead, {}, rg::kStageCompute);
    }
    pass.use(refs.output, rg::Access::StorageWrite, {}, rg::kStageCompute);
    if (dump.valid()) {
        pass.use(dump, rg::Access::StorageWrite, rg::BufferRange{0, static_cast<u64>(m_width) * m_height * 16u},
                 rg::kStageCompute);
    }
    ++m_stats.shadePasses;
}

void ClusteredLighting::recordDispatch(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const ClusteredLighting& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_pipelines[r.kernel]));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_layoutHandle, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_layoutHandle), VK_SHADER_STAGE_COMPUTE_BIT, 0, kPushBytes,
                       &r.push);
    vkCmdDispatch(cmd, r.groups[0], r.groups[1], r.groups[2]);
#else
    (void)context;
    (void)user;
#endif
}

} // namespace fuse::renderer::lighting_gpu
